<label>Buchwert nach der Bewertung / Restbuchwert des abgegangenen Anteils · EUR<input class="form-control" inputmode="decimal" name="<?= e($prefix.'[book]') ?>" value="<?= e(input($row,'book')) ?>"></label></div>
