<label class="check"><input class="check" type="checkbox" name="<?= e($prefix.'[permanent]') ?>" value="1" <?= input($row,'permanent')==='1'?'checked':'' ?>>Die Wertminderung ist nach dem Originalnachweis dauerhaft.</label>
